import { CommonModule } from '@angular/common';
import { Component, EventEmitter, Input, Output } from '@angular/core';

//#region Types
/* ----- Badge Types ----- */
type BadgeColor = 'gray' | 'green' | 'red' | 'orange' | 'purple' | 'teal';
type BadgeAppearance = 'solid' | 'subtle' | 'outline';
type BadgeSize = 'sm' | 'md' | 'lg';
type BadgeShape = 'rounded' | 'pill' | 'square';
type IconPosition = 'start' | 'end';
type AnimationType = 'none' | 'pop' | 'pulse' | 'fade';
//#endregion

//#region Badge Config Interface
/* ----- Badge Config Interface ----- */
export interface BadgeConfig {
  color: string;
  label?: string;
  icon?: string;
  show?: boolean;
}
//#endregion
@Component({
  selector: 'app-badge',
  imports: [CommonModule],
  templateUrl: './badge.html',
  styleUrl: './badge.scss',
})
export class Badge {
  //#region Inputs and Outputs
  /* ----- Inputs and Outputs ----- */
  @Input() color: BadgeColor = 'gray';
  @Input() appearance: BadgeAppearance = 'solid';
  @Input() label?: string;
  @Input() size: BadgeSize = 'md';
  @Input() shape: BadgeShape = 'rounded';
  @Input() icon?: string;
  @Input() iconPosition: IconPosition = 'start';
  @Input() badges?: BadgeConfig[];
  @Input() show = true;
  @Input() isClickable = false;
  @Input() disabled = false;
  @Input() backgroundColor?: string;
  @Input() textColor?: string;
  @Input() borderColor?: string;
  @Input() animation: AnimationType = 'none';
  @Output() onClick = new EventEmitter<void>();
  //#endregion

  //#region Methods
  /** Compute ARIA label for accessibility */
  public get ariaLabel() {
    const parts = [];
    if (this.label) parts.push(this.label);
    return parts.join(' ') || 'badge';
  }

  /** Handle badge click event */
  public handleClick(): void {
    if (this.isClickable && !this.disabled) {
      this.onClick.emit();
    }
  }
  //#endregion
}

import { Component, Input } from '@angular/core';
export interface NavChild {
  label: string;
  icon?: string;
}

export interface NavItem {
  icon: string;
  label: string;
  children?: NavChild[];
}
@Component({
  selector: 'app-navigation',
  imports: [],
  templateUrl: './navigation.html',
  styleUrl: './navigation.scss',
})
export class Navigation {
  @Input() expanded = false;
  @Input() showParentIcons = true;
  @Input() showChildIcons = true;
  @Input() showLogo = true;
  @Input() activeIndex: number | null = null;
  @Input() openIndex: number | null = null;
  hoveredIndex: number | null = null;
  activeChild: { parent: number; index: number } | null = null;

  navItems: NavItem[] = [];
  hoverY = 0;
  panelTop: number = 0;
  onHover(index: number, event: MouseEvent) {
    const target = event.currentTarget as HTMLElement;
    const rect = target.getBoundingClientRect();
    this.panelTop = rect.top;
    this.hoveredIndex = index;

    this.hoverY = rect.top + rect.height / 2;
  }
  onHoverChildClick(parentIndex: number, childIndex: number) {
    this.expanded = true;
    this.activeIndex = parentIndex;
    this.openIndex = parentIndex;
    this.activeChild = {
      parent: parentIndex,
      index: childIndex,
    };
    this.hoveredIndex = null;
  }

  onParentClick(index: number, hasChildren: boolean) {

    if (this.openIndex === index) {
      this.openIndex = null;
      this.activeChild = null;
      return;
    }

    this.activeIndex = index;

    if (hasChildren) {
      this.openIndex = index;

      this.activeChild = {
        parent: index,
        index: 0
      };
    } else {
      this.openIndex = null;
      this.activeChild = null;
    }
  }


  toggle() {
    this.expanded = !this.expanded;

    if (!this.expanded) {
      this.activeIndex = null;
      this.openIndex = null;
      this.activeChild = null;
    }
  }

  toggleItem(index: number) {
    this.activeIndex = this.activeIndex === index ? null : index;
    this.activeChild = null;
  }

  selectChild(parentIndex: number, childIndex: number) {
    this.activeIndex = parentIndex;
    this.activeChild = {
      parent: parentIndex,
      index: childIndex
    };
  }
}

