/* ----- BASE STYLES ----- */
.storybook-button {
  display: inline-block;
  cursor: pointer;
  font-weight: 700;
  line-height: 1;
  font-family: 'Nunito Sans', 'Helvetica Neue', Helvetica, Arial, sans-serif;
}

/* ----- VARIANTS ----- */
.storybook-button--primary {
  background-color: #555ab9;
  color: white;
}

.storybook-button--secondary {
  box-shadow: rgba(0, 0, 0, 0.15) 0px 0px 0px 1px inset;
  background-color: transparent;
  color: #333;
}

.storybook-button--danger {
  background-color: #dc2626;
  color: #ffffff;
}

.storybook-button--danger:hover {
  background-color: #b91c1c;
}

.storybook-button--danger:active {
  background-color: #991b1b;
}

/* ----- SIZES ----- */
.storybook-button--small {
  padding: 10px 16px;
  font-size: 12px;
}

.storybook-button--medium {
  padding: 11px 20px;
  font-size: 14px;
}

.storybook-button--large {
  padding: 12px 24px;
  font-size: 16px;
}

/* Shapes */
.storybook-button--rounded{border-radius:6px;}
.storybook-button--pill{border-radius:999px;}
.storybook-button--square{border-radius:3px;}

/* Disabled */
.storybook-button--disabled{opacity:.4;cursor:not-allowed;pointer-events:none;}

